  [446228] = { "遠隔攻撃力と近接攻撃力を$N1増加させます。このフラスコの効果は、悪夢の影響下にある地域でのみ有効です。", "近接攻撃力と遠隔攻撃力が$N1上昇しています。", 0x8e6cd2a6, 0x8ba8f8a1, "uu" },
  [446240] = { "Living Dreamsの魔法の印章を得て、$D1の間、呪文による与えるダメージと回復量を最大$N1増加させ、攻撃力を$N2増加させます。これは戦闘外でのみ使用できます。", "Living Dreamsの力を得ています。呪文によるダメージと治療量が最大$N1増加し、攻撃力が$N2上昇しています。", 0xc51c03e4, 0xeba25fac, "uu" },
  [446256] = { "呪文の威力を$N1増加させます。呪文が命中すると、一定の確率で対象にShadow Boltを放ちます。一度に有効にできるAtal'aiのポーションは1種類だけです。Sunken Temple以外では効果がありません。", "呪文の威力が$N1上昇しています。呪文が命中すると、目標にShadow Boltを放つことがあります。", 0x89a188a5, 0x971b518e, "uu" },
