  [446297] = { "$D1の間、呪文ダメージを最大96、回復量を最大192増加させます。呪文を唱えるたびに、ボーナスは呪文ダメージ8、回復量16ずつ減少します。", nil, 0x90476430, nil, "um" },
  [446310] = { "$D1の間、armorを1000、防御スキルを20増加させます。近接または遠隔のダメージを受けるたびに、このボーナスはarmor 100、防御2ずつ減少します。", nil, 0xc82a5ea7, nil, "um" },
  [446317] = { "敵の対象から生命力を$N1奪います。", nil, 0x8e44b266, nil, "um" },
